conclusions={1:('\u80fd\u67e5\u5230：\u5de6\u8f6c\u9053\u8def\u5f53\u524d\u662f\u7eff\u706f。','\u8fd9\u7ed9“\u7b49\u7eff\u706f\u540e\u5de6\u8f6c”\u63d0\u4f9b\u4e86\u5f53\u524d\u706f\u8272，\u4f46\u672c\u8f6e\u6ca1\u6709\u6d4b\u8bd5\u7b49\u706f、\u8d77\u6b65、\u5b8c\u6210\u5de6\u8f6c\u7684\u5b8c\u6574\u8fc7\u7a0b。'),2:('\u8bfb\u5230\u4e86\u5468\u56f4\u5bf9\u8c61\u7684\u4f4d\u7f6e，\u4f46\u6ca1\u6709\u67e5\u5230\u5f53\u524d\u706f\u8272。','\u8fd9\u6b21\u9053\u8def\u9009\u62e9\u7a0b\u5e8f\u627e\u5230\u4e86\u5de6\u8f6c\u9053\u8def；\u5bf9\u53f3\u8f6c\u6307\u4ee4\u53ea\u8fd4\u56de\u7ee7\u7eed\u6cbf\u8def\u8d70，\u4e0d\u80fd\u7b97\u53f3\u8f6c\u6210\u529f。'),3:('\u8bfb\u5230\u4e86\u5468\u56f4\u5bf9\u8c61\u7684\u4f4d\u7f6e，\u4f46\u6ca1\u6709\u67e5\u5230\u5f53\u524d\u706f\u8272。','\u8fd9\u6b21\u9053\u8def\u9009\u62e9\u7a0b\u5e8f\u627e\u5230\u4e86\u5de6\u8f6c\u9053\u8def；\u5c1a\u672a\u628a“\u6307\u5b9a\u8f66\u8f86”\u4e0e\u753b\u9762\u91cc\u7684\u8f66\u8f86\u5bf9\u5e94\u8d77\u6765。'),4:('\u8bfb\u5230\u4e86\u5468\u56f4\u5bf9\u8c61\u7684\u4f4d\u7f6e；\u8fd9\u6b21\u6ca1\u6709\u627e\u5230\u7b26\u5408\u5de6\u53f3\u8f6c\u6307\u4ee4\u7684\u9053\u8def。','\u7a0b\u5e8f\u8fd4\u56de\u7684\u662f\u7ee7\u7eed\u6cbf\u9053\u8def\u8d70，\u4e0d\u80fd\u5f53\u4f5c\u5de6\u53f3\u8f6c\u6210\u529f。\u8fd9\u662f\u5f53\u524d\u7a0b\u5e8f\u7684\u7ed3\u679c，\u4e0d\u4ee3\u8868\u771f\u5b9e\u573a\u666f\u4e00\u5b9a\u4e0d\u80fd\u8f6c。'),5:('\u8bfb\u5230\u4e86\u5468\u56f4\u5bf9\u8c61\u7684\u4f4d\u7f6e，\u4f46\u6ca1\u6709\u67e5\u5230\u5f53\u524d\u706f\u8272。','\u7a0b\u5e8f\u627e\u5230\u4e86\u5de6\u53f3\u8f6c\u9053\u8def；\u627e\u5230\u9053\u8def\u4e0d\u7b49\u4e8e\u8f68\u8ff9\u5b8c\u6210，\u8fd9\u8f6e\u6ca1\u6709\u91cd\u65b0\u9a8c\u8bc1\u8fd9\u4e9b\u52a8\u4f5c\u7684\u6267\u884c。'),6:('\u80fd\u67e5\u5230：\u5de6\u8f6c\u9053\u8def\u5f53\u524d\u662f\u7ea2\u706f。','\u8f93\u5165“\u7b49\u7eff\u706f\u540e\u5de6\u8f6c”\u65f6，\u7a0b\u5e8f\u73b0\u5728\u80fd\u8bf4\u660e：\u76ee\u6807\u9053\u8def\u5f53\u524d\u662f\u7ea2\u706f。\u5c1a\u672a\u5b9e\u73b0\u6301\u7eed\u89c2\u5bdf\u5230\u7eff\u706f\u540e\u81ea\u52a8\u8d77\u6b65。'),7:('\u5730\u56fe\u91cc\u627e\u5230\u4e86\u4e0e\u53f3\u8f6c\u5165\u53e3\u5173\u8054\u7684\u505c\u8f66\u6807\u5fd7\u533a\u57df。','“\u5728\u505c\u8f66\u6807\u5fd7\u5904\u53f3\u8f6c”\u6709\u4e86\u5730\u56fe\u7ebf\u7d22，\u4f46\u8fd8\u6ca1\u6709\u8bc1\u660e\u8f66\u5df2\u5230\u505c\u8f66\u4f4d\u7f6e，\u4e5f\u6ca1\u6709\u5b8c\u6210\u505c\u8f66\u540e\u53f3\u8f6c。')}
