index='<h1>\u8fd9\u8f6e\u7a0b\u5e8f\u7a76\u7adf\u77e5\u9053\u4e86\u4ec0\u4e48？</h1><section class="result"><h2>\u7ed3\u8bba：\u80fd\u8bfb\u53d6\u90e8\u5206\u73af\u5883\u4fe1\u606f，\u8fd8\u4e0d\u80fd\u6267\u884c\u5168\u90e8 doPlan \u6307\u4ee4。</h2><p>\u5df2\u7ecf\u786e\u8ba4：<b>\u573a\u666f 1 \u7684\u5de6\u8f6c\u706f\u662f\u7eff\u706f，\u573a\u666f 6 \u7684\u5de6\u8f6c\u706f\u662f\u7ea2\u706f，\u573a\u666f 7 \u7684\u5730\u56fe\u6709\u505c\u8f66\u6807\u5fd7\u533a\u57df。</b>\u8fd9\u4e9b\u6765\u81ea nuPlan \u6570\u636e\u5e93\u548c\u5730\u56fe，\u4e0d\u662f AI \u770b\u89c6\u9891\u8bc6\u522b\u51fa\u6765\u7684。</p><p>\u4e03\u4e2a\u573a\u666f\u90fd\u8bfb\u5230\u4e86\u5176\u4ed6\u4ea4\u901a\u53c2\u4e0e\u8005\u7684\u4f4d\u7f6e，\u5e76\u63d0\u53d6\u4e86\u524d\u89c6\u89c6\u9891\u53c2\u8003\u5e27。<b>\u8fd8\u6ca1\u6709\u81ea\u52a8\u786e\u8ba4“\u54ea\u8f86\u662f\u9ed1\u8272 SUV”“\u54ea\u680b\u662f\u6307\u4ee4\u8bf4\u7684\u697c”。</b></p><p>\u672c\u62a5\u544a\u68c0\u67e5\u7684\u662f“\u73af\u5883\u4fe1\u606f\u662f\u5426\u8bfb\u5230、\u662f\u5426\u5bf9\u5e94\u5f97\u4e0a”，\u4e0d\u662f\u9a7e\u9a76\u6210\u529f\u7387\u62a5\u544a。</p></section><section><h2>\u4e09\u4e2a\u6b65\u9aa4，\u5206\u522b\u505a\u5230\u54ea\u91cc\u4e86？</h2><table><tr><th>\u6b65\u9aa4</th><th>\u901a\u4fd7\u89e3\u91ca</th><th>\u672c\u8f6e\u7ed3\u679c</th></tr><tr><td>\u8bfb\u53d6\u73af\u5883</td><td>\u67e5\u6570\u636e\u5e93：\u8f66\u5728\u54ea\u91cc、\u8def\u53e3\u706f\u662f\u4ec0\u4e48\u989c\u8272。</td><td>\u5df2\u5b8c\u6210\u4e03\u4e2a\u56fa\u5b9a\u65f6\u523b\u7684\u8bfb\u53d6；\u90e8\u5206\u65f6\u523b\u6ca1\u6709\u706f\u8272\u8bb0\u5f55。</td></tr><tr><td>\u628a\u89c6\u9891\u548c\u5730\u56fe\u5bf9\u5e94\u8d77\u6765</td><td>\u786e\u8ba4\u753b\u9762\u91cc\u7684\u4e00\u8f86\u8f66，\u5c31\u662f\u5730\u56fe\u4e0a\u7684\u54ea\u4e00\u4e2a\u70b9。</td><td>\u753b\u51fa\u4e86\u5bf9\u7167\u56fe，\u5c1a\u672a\u9a8c\u8bc1\u5339\u914d\u51c6\u786e\u7387。</td></tr><tr><td>\u6309\u73af\u5883\u6267\u884c\u6307\u4ee4</td><td>\u4f8b\u5982\u7b49\u5230\u7eff\u706f，\u518d\u5de6\u8f6c；\u8ddf\u968f\u6307\u5b9a\u8f66\u8f86。</td><td>\u5c1a\u672a\u8dd1\u901a\u5b8c\u6574\u8fc7\u7a0b。\u73b0\u5728\u80fd\u89e3\u91ca\u90e8\u5206\u7b49\u5f85\u539f\u56e0。</td></tr></table></section><section><h2>\u9010\u4e2a\u573a\u666f\u770b\u7ed3\u8bba</h2><table><tr><th>\u573a\u666f</th><th>\u672c\u8f6e\u53d1\u73b0</th><th>\u67e5\u770b\u56fe\u7247\u548c\u89e3\u91ca</th></tr>'
