 body+=f'</table></section><section><h2>2．\u5730\u56fe\u56fe：\u7cfb\u7edf\u77e5\u9053\u54ea\u4e9b\u5bf9\u8c61\u5728\u54ea\u91cc？</h2><p><b>\u9ed1\u70b9：</b>\u6211\u4eec\u63a7\u5236\u7684\u8f66\u5728\u8fd9\u4e2a\u65f6\u523b\u7684\u4f4d\u7f6e。<b>\u7070\u7ebf：</b>\u5730\u56fe\u4e2d\u8f66\u9053\u4e2d\u592e\u7684\u53c2\u8003\u7ebf，\u4e0d\u662f\u8f66\u9053\u8fb9\u754c、\u5b9e\u7ebf\u6216\u5141\u8bb8\u6362\u9053\u7684\u6807\u5fd7。<b>\u9752\u7eff\u8272\u70b9：</b>\u6570\u636e\u5e93\u8bb0\u5f55\u7684\u5176\u4ed6\u5bf9\u8c61\u4e2d\u5fc3，\u53ef\u80fd\u662f\u8f66\u8f86、\u884c\u4eba\u6216\u5176\u4ed6\u7c7b\u522b，\u5e76\u975e\u5168\u662f\u6c7d\u8f66。</p><p><b>\u600e\u4e48\u770b：</b>\u5148\u627e\u5230\u9ed1\u70b9，\u518d\u770b\u9644\u8fd1\u7684\u9752\u7eff\u8272\u70b9\u5206\u5e03\u5728\u54ea\u91cc。\u8fd9\u5f20\u56fe\u53ea\u8868\u8fbe\u5bf9\u8c61\u4f4d\u7f6e，\u4e0d\u663e\u793a\u62e5\u6324\u7684\u6280\u672f\u7f16\u53f7；\u89c6\u9891\u4e2d\u7684\u7f16\u53f7\u4f1a\u5728\u540e\u9762\u5355\u72ec\u89e3\u91ca。</p><img src="map-readable-{n:02d}.png" alt="\u5730\u56fe\u9053\u8def\u548c\u5bf9\u8c61\u4f4d\u7f6e"><p><b>\u672c\u56fe\u7ed3\u8bba：</b>\u7a0b\u5e8f\u8bfb\u53d6\u4e86 {len(r["objects"])} \u4e2a\u5bf9\u8c61；\u6b64\u653e\u5927\u8303\u56f4\u663e\u793a {len(visible)} \u4e2a。\u5b83\u77e5\u9053\u4f4d\u7f6e，\u4f46\u8fd8\u4e0d\u77e5\u9053\u5176\u4e2d\u54ea\u4e00\u4e2a\u7b26\u5408“\u9ed1\u8272 SUV”\u8fd9\u6837\u7684\u6587\u5b57\u63cf\u8ff0。</p></section>'
 mapping=r['video']['mapping_status'];vtext='\u5df2\u6709\u6309\u6444\u50cf\u5934\u8bb0\u5f55\u5efa\u7acb\u7684\u6761\u4ef6\u5bf9\u5e94\u5173\u7cfb，\u4f46\u4e0d\u662f\u9010\u5e27\u4eba\u5de5\u786e\u8ba4。' if mapping=='conditional_camera_lookup' else '\u76ee\u524d\u53ea\u662f\u6309 GPS \u884c\u53f7\u9009\u53d6\u89c6\u9891\u5e27，\u8fd8\u6ca1\u6709\u9a8c\u8bc1\u8fd9\u4e24\u8005\u80fd\u5426\u76f4\u63a5\u5bf9\u5e94。'
 body+=f'<section><h2>3．\u89c6\u9891\u56fe：\u4eba\u773c\u80fd\u770b\u5230\u4ec0\u4e48？</h2><p>\u8fd9\u662f\u672c\u5730\u524d\u89c6\u89c6\u9891\u7684\u4e00\u5e27，\u53ef\u4ee5\u5e2e\u52a9\u4f60\u770b\u61c2\u9053\u8def\u548c\u5468\u56f4\u8f66\u8f86。<b>\u5b83\u53ea\u662f\u53c2\u8003\u753b\u9762，\u4e0d\u662f\u7a0b\u5e8f\u5df2\u7ecf\u8ba4\u51fa\u8fd9\u4e9b\u7269\u4f53\u7684\u7ed3\u679c。</b></p><img src="video-{n:02d}.jpg" alt="\u524d\u89c6\u89c6\u9891\u53c2\u8003\u5e27"><p><b>\u672c\u56fe\u7ed3\u8bba：</b>{vtext}\u9009\u53d6\u7684 GPS \u8bb0\u5f55\u4e0e\u6d4b\u8bd5\u65f6\u523b\u76f8\u5dee {r["video"]["gps_time_residual_s"]:.3f} \u79d2；\u8fd9\u4e2a\u65f6\u95f4\u5dee\u5c0f，\u4e5f\u4e0d\u80fd\u5355\u72ec\u8bc1\u660e\u89c6\u9891\u5e27\u5bf9\u5e94\u6b63\u786e。</p></section>'
 body+=f'<section><h2>4．\u9ec4\u8272\u70b9\u56fe：\u6570\u636e\u5e93\u91cc\u7684\u5bf9\u8c61\u80fd\u5bf9\u5230\u753b\u9762\u4e0a\u5417？</h2><p>\u7a0b\u5e8f\u7528\u6444\u50cf\u5934\u7684\u4f4d\u7f6e、\u671d\u5411\u548c\u955c\u5934\u53c2\u6570，\u628a\u6570\u636e\u5e93\u7684\u4e09\u7ef4\u5bf9\u8c61\u4e2d\u5fc3\u6362\u7b97\u6210\u753b\u9762\u4e0a\u7684\u4f4d\u7f6e，\u753b\u6210<b>\u9ec4\u8272\u70b9</b>。\u8fd9\u5c31\u662f“\u6295\u5f71”。<b>\u7ea2\u8272\u5b57\u6bcd\u6570\u5b57</b>\u662f\u5bf9\u8c61\u7f16\u53f7，\u4e0d\u662f AI \u8bc6\u522b\u51fa\u7684\u540d\u79f0。</p><p><b>\u4e0a\u56fe：</b>\u5047\u8bbe\u89c6\u9891\u5df2\u7ecf\u6821\u6b63\u4e86\u955c\u5934\u9020\u6210\u7684\u53d8\u5f62。<b>\u4e0b\u56fe：</b>\u5047\u8bbe\u89c6\u9891\u4ecd\u4fdd\u7559\u955c\u5934\u53d8\u5f62。\u6b63\u5728\u6bd4\u8f83\u4e24\u79cd\u60c5\u51b5；\u4e0d\u662f\u4e24\u4e2a\u65f6\u523b，\u4e5f\u4e0d\u662f\u6210\u529f\u4e0e\u5931\u8d25\u7684\u5bf9\u6bd4。</p><img src="projection-{n:02d}.jpg" alt="\u4e24\u79cd\u955c\u5934\u5904\u7406\u5047\u8bbe\u4e0b\u7684\u5bf9\u8c61\u6295\u5f71"><p><b>\u672c\u56fe\u7ed3\u8bba：\u8fd8\u6ca1\u6709\u5b8c\u6210\u9a8c\u8bc1。</b>\u4e00\u4e9b\u70b9\u843d\u5728\u8f66\u8f86\u9644\u8fd1\u53ea\u80fd\u4f5c\u4e3a\u7ebf\u7d22。\u9700\u8981\u6838\u5bf9\u5e27\u65f6\u95f4、\u955c\u5934\u5904\u7406\u65b9\u5f0f\u548c\u591a\u4e2a\u5bf9\u8c61，\u624d\u80fd\u628a“\u89c6\u9891\u91cc\u8ba4\u51fa\u7684\u8f66\u8f86”\u53ef\u9760\u5730\u7ed1\u5b9a\u5230\u5730\u56fe\u5bf9\u8c61。</p><p><b>\u4e0b\u4e00\u6b65：</b>\u5148\u9a8c\u8bc1\u8fd9\u4e00\u6b65\u5bf9\u5e94\u5173\u7cfb，\u518d\u8bc6\u522b\u989c\u8272、\u8f66\u578b\u548c\u5efa\u7b51\u63cf\u8ff0。\u5426\u5219\u5373\u4f7f\u8ba4\u51fa\u4e86\u9ed1\u8272 SUV，\u4e5f\u53ef\u80fd\u6307\u5411\u5730\u56fe\u91cc\u7684\u53e6\u4e00\u8f86\u8f66。</p></section>'
 body+='<details><summary>\u6280\u672f\u8be6\u60c5：\u539f\u59cb\u9053\u8def\u7f16\u53f7、\u65f6\u95f4\u548c\u8bb0\u5f55</summary><pre style="white-space:pre-wrap;font-size:13px">'+html.escape(json.dumps({'timestamp_us':r['timestamp_us'],'routes':r['routes'],'video':r['video']},ensure_ascii=False,indent=2))+'</pre></details>'
