index+='</table></section><section><h2>\u8bfb\u56fe\u65f6\u8bb0\u4f4f\u8fd9\u56db\u70b9</h2><ul><li>\u8bfb\u5230\u4f4d\u7f6e，\u4e0d\u7b49\u4e8e\u8ba4\u51fa\u4e86\u989c\u8272\u548c\u8f66\u578b。</li><li>\u627e\u5230\u9053\u8def，\u4e0d\u7b49\u4e8e\u5df2\u7ecf\u751f\u6210\u5e76\u5b8c\u6210\u4e86\u9a7e\u9a76\u8f68\u8ff9。</li><li>\u6ca1\u6709\u706f\u8272\u8bb0\u5f55，\u4e0d\u7b49\u4e8e\u7eff\u706f\u6216\u6ca1\u6709\u7ea2\u7eff\u706f。</li><li>\u9ec4\u8272\u70b9\u843d\u5728\u8f66\u9644\u8fd1，\u4e0d\u7b49\u4e8e\u89c6\u9891\u4e0e\u5730\u56fe\u5df2\u7ecf\u5339\u914d\u9a8c\u8bc1\u901a\u8fc7。</li></ul></section>'
